{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Direct 2022 evidence on personal command-and-control or internal nuclear-security decisions is thin, so the chapter leans on limited-exposure and treaty-posture context.",
          "lenses": ["1B.3", "1B.7", "1B.9"],
          "best_source_or_query_direction": "IAEA safeguards/incident documentation, Egyptian nuclear-regulator records, and contemporaneous official security or licensing materials",
          "why_it_matters": "It would strengthen attribution from civilian nuclear posture to ruler-specific risk management."
        }
      ],
      "reason": "The package fairly separates Egypt’s limited nuclear exposure, civilian El-Dabaa activity, treaty posture, and disarmament rhetoric from any weapons-use or brinkmanship claim. The remaining weakness is depth of direct 2022 safety-governance evidence, not a fairness defect."
    },
    {
      "chapter_id": "2B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0025",
          "reason": "Domestic rights-abuse reporting is chapter-3B context, not direct international peace or aggression evidence."
        },
        {
          "evidence_id": "E0026",
          "reason": "Pardon-committee and emergency-powers material is domestic safety/political-control context, not international conduct evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "The chapter still leans heavily on diplomatic posture and mediation, with limited direct evidence of durable conflict de-escalation outcomes attributable to Sisi in 2022.",
          "lenses": ["2B.1", "2B.7", "2B.10"],
          "best_source_or_query_direction": "UN mediation records, ceasefire monitoring, and contemporaneous third-party reporting on Egypt’s role in Gaza, Libya, and Turkey mediation",
          "why_it_matters": "It would separate rhetorical restraint from demonstrated international-security effect."
        }
      ],
      "reason": "The foreign-policy evidence is broadly on target, but two domestic-rights items are misfiled into this chapter and should not be used as peace/aggression evidence. The rest of the dossier is usable, but the contamination is enough to require cleanup."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Independent, countable 2022 microdata on disappearances, torture, and local protection failures remains incomplete.",
          "lenses": ["3B.1", "3B.2", "3B.7"],
          "best_source_or_query_direction": "UN human-rights mechanisms, named case tracking, and locally documented detention/protest datasets",
          "why_it_matters": "It would sharpen severity and scale without changing the basic repression finding."
        }
      ],
      "reason": "The package fairly balances severe repression, limited remedial action, and official reform claims, with clear attribution and contrary evidence. The main weakness is evidentiary granularity, not chapter integrity."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "No 2022 election or transfer event exists to directly test contestability, so several lenses rest on structural evidence and the national-dialogue record.",
          "lenses": ["4B.1", "4B.8"],
          "best_source_or_query_direction": "Election-law, party, court-independence, and media-freedom documentation from 2022",
          "why_it_matters": "It would distinguish structural authoritarianism from direct ruler action in the target year."
        }
      ],
      "reason": "The package fairly presents political closure, media repression, selective releases, and the state-framed dialogue as competing interpretations. The evidence is mostly relevant, and the uncertainty is explicit."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Implementation quality is clearer than household-level welfare impact, but independent 2022 microdata on distribution, poverty, and inflation pass-through remains thin.",
          "lenses": ["5B.8", "5B.9", "5B.10"],
          "best_source_or_query_direction": "Household survey microdata, CAPMAS series, and independent poverty/inflation impact analyses for 2022",
          "why_it_matters": "It would distinguish policy intent and macro stabilization from actual ordinary-life outcomes."
        }
      ],
      "reason": "The package fairly shows crisis management, reform signaling, state-ownership policy, and negative macro outcomes. The evidence is mixed but coherent, and the attribution caveats are appropriate."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Direct, independent 2022 household outcome evidence is still thinner than policy-announcement evidence, especially for quality, nutrition, disability access, and subnational variation.",
          "lenses": ["6B.2", "6B.3", "6B.8", "6B.10"],
          "best_source_or_query_direction": "Household surveys, UNICEF/World Bank poverty microdata, and program evaluation evidence for Egypt in 2022",
          "why_it_matters": "It would tighten the link between spending, access, and life-chance change."
        }
      ],
      "reason": "The package fairly balances large social-protection efforts, targeted vulnerable-group programs, and inflation-driven welfare pressure. The remaining weakness is outcome resolution, not package fairness."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0025",
          "reason": "Country-level repression reporting does not establish ruler-specific personal dishonesty or self-enrichment."
        },
        {
          "evidence_id": "E0030",
          "reason": "Protest-arrest reporting is relevant to repression, but not by itself to personal integrity absent a clearer personal-nexus showing."
        },
        {
          "evidence_id": "E0031",
          "reason": "Journalist-detention reporting is mainly 4B/3B context unless tied to Sisi’s own truthfulness, benefit, or concealment."
        },
        {
          "evidence_id": "E0044",
          "reason": "Campaign-style detention evidence shows coercion, but not a direct personal-integrity nexus without stronger proof of Sisi’s own deception or concealment."
        },
        {
          "evidence_id": "E0084",
          "reason": "Amnesty’s protest-crackdown evidence is strong on repression, but it does not itself prove personal dishonesty or self-dealing."
        },
        {
          "evidence_id": "E0085",
          "reason": "Year-end repression synthesis should not substitute for direct integrity evidence about Sisi’s personal conduct."
        },
        {
          "evidence_id": "E0092",
          "reason": "Press-freedom violations are relevant to obstruction of scrutiny, but the package lacks a direct personal-benefit or personal-deception chain."
        },
        {
          "evidence_id": "E0094",
          "reason": "Pre-COP27 arrests support repression and retaliation, not direct personal integrity findings by themselves."
        },
        {
          "evidence_id": "E0095",
          "reason": "The arrest of a journalist for reporting prison abuse is meaningful context, but it still needs a clearer personal-nexus justification for 7B weight."
        },
        {
          "evidence_id": "E0096",
          "reason": "Journalist detention is relevant to scrutiny suppression, but not sufficient on its own to prove ruler-specific dishonesty."
        }
      ],
      "material_gaps": [
        {
          "gap": "The package lacks direct 2022 personal-nexus evidence such as asset declarations, audit findings, procurement records, sworn contradictions, or family enrichment links.",
          "lenses": ["7B.1", "7B.3", "7B.4", "7B.6"],
          "best_source_or_query_direction": "Asset-declaration records, court or audit findings, procurement files, and investigative reporting tied to Sisi or close family members",
          "why_it_matters": "The chapter guide requires ruler-specific integrity evidence, not generalized repression or country corruption."
        },
        {
          "gap": "Truthfulness/correction evidence is still mostly inferential and not forensic.",
          "lenses": ["7B.1", "7B.2", "7B.8"],
          "best_source_or_query_direction": "Direct transcript-based fact checks, official corrections, sworn testimony, and documented retractions from 2022",
          "why_it_matters": "It would distinguish ordinary authoritarian messaging from personal dishonesty."
        }
      ],
      "reason": "This chapter is the main package-level problem. Most of the evidence is repression and institution-control material that belongs in 3B/4B unless a direct personal dishonesty, benefit, concealment, or accountability nexus is shown. The dossier does not yet clear that admissibility gate."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "The program portfolio is substantially clearer now, but direct evidence of Sisi personally steering tactical adjustments remains limited.",
          "lenses": ["8B.1", "8B.8", "8B.9"],
          "best_source_or_query_direction": "Program documents, cabinet directives, implementation reviews, and contemporaneous records showing personnel replacement or course correction",
          "why_it_matters": "It would strengthen the causal chain from stated program to ruler-driven execution."
        }
      ],
      "reason": "The package now presents a coherent 2022 program of stabilization, state-footprint reduction, and social protection, with some implementation and mixed outcomes. The remaining weakness is granularity, not overall fairness."
    }
  ]
}
